INSERT INTO etl_formula_help
    (function_name, category, syntax, summary, usage_text, examples_json, notice, sort_order)
VALUES
    ('CHAR_LENGTH', '문자열', 'CHAR_LENGTH(문자열)', '문자열의 문자 개수를 구합니다.', '문자열의 문자 개수를 구합니다.', '[{"formula":"CHAR_LENGTH(''apache'')","description":"문자열 ''apache''의 문자 개수인 6을 반환합니다.","result":"6"}]', 'Oracle의 LENGTH와 동일 기능이지만, Oracle은 바이트 단위(LENGTHB)와 문자 단위(LENGTH)를 구분합니다.', 1),
    ('CHARACTER_LENGTH', '문자열', 'CHARACTER_LENGTH(문자열)', 'CHAR_LENGTH와 동일하게 문자열의 문자 수를 구합니다.', 'CHAR_LENGTH와 동일하게 문자열의 문자 수를 구합니다.', '[{"formula":"CHARACTER_LENGTH(''calcite'')","description":"문자열 ''calcite''의 문자 개수인 7을 반환합니다.","result":"7"}]', 'Oracle에는 CHARACTER_LENGTH가 없고 LENGTH만 사용합니다. 표준 SQL 함수명입니다.', 2),
    ('UPPER', '문자열', 'UPPER(문자열)', '영문 알파벳을 대문자로 변환합니다.', '영문 알파벳을 대문자로 변환합니다.', '[{"formula":"UPPER(''hello'')","description":"''hello''를 대문자로 변환한 ''HELLO''를 반환합니다.","result":"HELLO"}]', 'Oracle과 동일하게 동작합니다. 다만 Oracle은 NLS_SORT 설정에 따라 로케일별 대소문자 규칙이 달라질 수 있습니다.', 3),
    ('LOWER', '문자열', 'LOWER(문자열)', '영문 알파벳을 소문자로 변환합니다.', '영문 알파벳을 소문자로 변환합니다.', '[{"formula":"LOWER(''WORLD'')","description":"''WORLD''를 소문자로 변환한 ''world''를 반환합니다.","result":"world"}]', 'Oracle과 동일하게 동작하여 혼동 우려가 적습니다.', 4),
    ('POSITION', '문자열', 'POSITION(찾을문자열 IN 대상문자열)', '문자열 안에서 부분 문자열이 처음 나타나는 위치를 찾습니다.', '문자열 안에서 부분 문자열이 처음 나타나는 위치를 찾습니다.', '[{"formula":"POSITION(''a'' IN ''apache'')","description":"''apache''에서 ''a''가 처음 나오는 위치인 1을 반환합니다.","result":"1"}]', 'Oracle에는 POSITION이 없고 대신 INSTR(대상문자열, 찾을문자열)을 사용합니다. 인자 순서가 반대이므로 주의가 필요합니다.', 5),
    ('TRIM', '문자열', 'TRIM([BOTH|LEADING|TRAILING] 제거할문자 FROM 문자열)', '문자열의 앞/뒤 공백 또는 지정 문자를 제거합니다.', '문자열의 앞/뒤 공백 또는 지정 문자를 제거합니다.', '[{"formula":"TRIM(BOTH ''x'' FROM ''xxhelloxx'')","description":"앞뒤의 ''x'' 문자를 모두 제거한 ''hello''를 반환합니다.","result":"hello"}]', 'Oracle의 TRIM은 단일 문자만 제거 가능하며, 여러 문자 제거 시 Oracle은 LTRIM/RTRIM(문자열, 문자셋)을 사용해야 합니다.', 6),
    ('SUBSTRING', '문자열', 'SUBSTRING(문자열 FROM 시작위치 [FOR 길이])', '문자열의 지정 위치부터 일부를 추출합니다.', '문자열의 지정 위치부터 일부를 추출합니다.', '[{"formula":"SUBSTRING(''20250115'' FROM 5 FOR 2)","description":"5번째 위치부터 2자리인 ''01''(월)을 반환합니다.","result":"1"}]', 'Oracle은 SUBSTR(문자열, 시작위치, 길이) 구문을 사용하며 콤마로 구분합니다. 또한 Oracle의 SUBSTR은 음수 시작위치(끝에서부터)를 지원하지만 Calcite의 SUBSTRING은 음수 위치를 지원하지 않습니다.', 7),
    ('OVERLAY', '문자열', 'OVERLAY(원본문자열 PLACING 삽입문자열 FROM 시작위치 [FOR 길이])', '문자열의 특정 구간을 다른 문자열로 치환합니다.', '문자열의 특정 구간을 다른 문자열로 치환합니다.', '[{"formula":"OVERLAY(''010-1234-5678'' PLACING ''****'' FROM 5 FOR 4)","description":"5번째 위치부터 4자리를 ''****''로 바꾼 ''010-****-5678''을 반환합니다.","result":"010-****-5678"}]', 'Oracle에는 OVERLAY 함수가 없으며, 동일 기능을 위해 SUBSTR과 문자열 연결(||)을 조합해서 직접 구현해야 합니다.', 8),
    ('INITCAP', '문자열', 'INITCAP(문자열)', '각 단어의 첫 글자를 대문자로, 나머지를 소문자로 변환합니다.', '각 단어의 첫 글자를 대문자로, 나머지를 소문자로 변환합니다.', '[{"formula":"INITCAP(''apache calcite'')","description":"각 단어 첫 글자를 대문자로 바꾼 ''Apache Calcite''를 반환합니다.","result":"Apache Calcite"}]', 'Oracle과 동일한 이름, 동일한 기능으로 제공되어 혼동 우려가 적습니다.', 9),
    ('|| (문자열 연결)', '문자열', '문자열1 || 문자열2', '두 문자열을 이어 붙입니다.', '두 문자열을 이어 붙입니다.', '[{"formula":"''홍'' || ''길동''","description":"두 문자열을 이어 붙인 ''홍길동''을 반환합니다.","result":"홍길동"}]', 'Oracle과 동일한 연산자를 사용하지만, Oracle은 NULL과 연결 시 NULL을 무시하고 나머지를 반환하는 반면 Calcite는 NULL이 포함되면 결과 전체가 NULL이 될 수 있습니다.', 10),
    ('LIKE', '문자열', '문자열 LIKE 패턴 [ESCAPE 이스케이프문자]', '와일드카드를 사용해 문자열 패턴을 비교합니다.', '와일드카드를 사용해 문자열 패턴을 비교합니다.', '[{"formula":"''apache_calcite'' LIKE ''apache$_%'' ESCAPE ''$''","description":"''_'' 문자를 이스케이프 처리하여 실제 언더바가 포함된 문자열만 매칭되어 TRUE를 반환합니다.","result":"TRUE"}]', '기본 와일드카드(%, _)와 ESCAPE 구문은 Oracle과 동일합니다.', 11),
    ('CONCAT', '문자열', 'CONCAT(문자열1, 문자열2, ...)', '여러 문자열을 하나로 연결합니다.', '여러 문자열을 하나로 연결합니다.', '[{"formula":"CONCAT(''202501'', ''15'')","description":"두 문자열을 연결한 ''20250115''를 반환합니다.","result":"20250115"}]', 'Oracle의 CONCAT은 인자를 2개만 받을 수 있어 3개 이상 연결 시 CONCAT을 중첩해야 합니다. Calcite는 여러 개를 한 번에 연결할 수 있습니다.', 12),
    ('REPLACE', '문자열', 'REPLACE(대상문자열, 찾을문자열, 바꿀문자열)', '문자열 내 특정 부분을 다른 문자열로 모두 치환합니다.', '문자열 내 특정 부분을 다른 문자열로 모두 치환합니다.', '[{"formula":"REPLACE(''2025-01-15'', ''-'', ''/'')","description":"''-''를 모두 ''/''로 바꾼 ''2025/01/15''를 반환합니다.","result":"2025-01-15"}]', 'Oracle과 구문 및 동작이 동일합니다.', 13),
    ('LPAD', '문자열', 'LPAD(문자열, 전체길이, 채울문자)', '문자열의 왼쪽을 지정 문자로 채워 지정 길이를 맞춥니다.', '문자열의 왼쪽을 지정 문자로 채워 지정 길이를 맞춥니다.', '[{"formula":"LPAD(''7'', 3, ''0'')","description":"''7''의 왼쪽을 ''0''으로 채워 길이 3인 ''007''을 반환합니다.","result":"7"}]', 'Oracle과 구문 및 동작이 동일하여 혼동 우려가 적습니다.', 14),
    ('RPAD', '문자열', 'RPAD(문자열, 전체길이, 채울문자)', '문자열의 오른쪽을 지정 문자로 채워 지정 길이를 맞춥니다.', '문자열의 오른쪽을 지정 문자로 채워 지정 길이를 맞춥니다.', '[{"formula":"RPAD(''AB'', 5, ''*'')","description":"''AB''의 오른쪽을 ''*''로 채워 길이 5인 ''AB***''를 반환합니다.","result":"AB***"}]', 'Oracle과 구문 및 동작이 동일하여 혼동 우려가 적습니다.', 15),
    ('ASCII', '문자열', 'ASCII(문자열)', '문자열 첫 글자의 아스키(또는 유니코드) 코드값을 반환합니다.', '문자열 첫 글자의 아스키(또는 유니코드) 코드값을 반환합니다.', '[{"formula":"ASCII(''A'')","description":"문자 ''A''의 코드값인 65를 반환합니다.","result":"65"}]', 'Oracle에도 동일한 이름과 기능의 함수가 있어 혼동 우려가 적습니다.', 16),
    ('CHR', '문자열', 'CHR(코드값)', '코드값에 해당하는 문자를 반환합니다.', '코드값에 해당하는 문자를 반환합니다.', '[{"formula":"CHR(65)","description":"코드값 65에 해당하는 문자 ''A''를 반환합니다.","result":"A"}]', 'Oracle과 이름 및 기능이 동일합니다.', 17),
    ('REGEXP_REPLACE', '문자열', 'REGEXP_REPLACE(문자열, 정규식패턴, 치환문자열)', '정규식 패턴에 매칭되는 부분을 다른 문자열로 치환합니다.', '정규식 패턴에 매칭되는 부분을 다른 문자열로 치환합니다.', '[{"formula":"REGEXP_REPLACE(''a1b2c3'', ''[0-9]'', '''')","description":"숫자를 모두 제거한 ''abc''를 반환합니다.","result":"abc"}]', 'Oracle은 REGEXP_REPLACE(문자열, 패턴, 치환문자열, 시작위치, 매칭occurrence, 매치옵션)까지 세밀하게 제어 가능하지만, Calcite는 기본 3개 인자만 지원하는 경우가 많아 고급 옵션에서 차이가 발생합니다.', 18),
    ('ABS', '숫자', 'ABS(숫자)', '주어진 숫자의 절댓값을 반환합니다.', '주어진 숫자의 절댓값을 반환합니다.', '[{"formula":"ABS(-5)","description":"-5의 절댓값인 5를 반환합니다.","result":"5"}]', 'Oracle과 이름, 동작이 동일하여 혼동 우려가 적습니다.', 19),
    ('ROUND', '숫자', 'ROUND(숫자, 반올림할자릿수)', '숫자를 지정한 소수 자리에서 반올림합니다.', '숫자를 지정한 소수 자리에서 반올림합니다.', '[{"formula":"ROUND(3.14159, 2)","description":"소수 둘째 자리까지 반올림한 3.14를 반환합니다.","result":"3.14"}]', 'Oracle은 자릿수에 음수를 넣으면 정수부(10의 자리, 100의 자리 등)를 반올림할 수 있습니다(예: ROUND(1250,-2)=1300). Calcite도 이를 지원하지만 방언에 따라 음수 자릿수 처리가 다를 수 있어 확인이 필요합니다.', 20),
    ('TRUNCATE', '숫자', 'TRUNCATE(숫자, 자릿수)', '숫자를 지정한 소수 자리에서 버림(절삭)합니다.', '숫자를 지정한 소수 자리에서 버림(절삭)합니다.', '[{"formula":"TRUNCATE(3.98, 1)","description":"소수 둘째 자리 이하를 버린 3.9를 반환합니다.","result":"3.9"}]', 'Oracle은 함수명이 TRUNC(숫자, 자릿수)이며, TRUNC는 날짜에도 사용 가능한 다목적 함수입니다. Calcite의 TRUNCATE는 숫자 전용이라는 점에서 혼동하기 쉽습니다.', 21),
    ('CEIL', '숫자', 'CEIL(숫자)', '숫자보다 크거나 같은 최소의 정수로 올림합니다.', '숫자보다 크거나 같은 최소의 정수로 올림합니다.', '[{"formula":"CEIL(3.14)","description":"3.14보다 크거나 같은 최소 정수인 4를 반환합니다.","result":"4"}]', 'Oracle과 이름, 동작이 동일합니다(CEILING도 동의어로 지원).', 22),
    ('FLOOR', '숫자', 'FLOOR(숫자)', '숫자보다 작거나 같은 최대의 정수로 내림합니다.', '숫자보다 작거나 같은 최대의 정수로 내림합니다.', '[{"formula":"FLOOR(3.99)","description":"3.99보다 작거나 같은 최대 정수인 3을 반환합니다.","result":"3"}]', 'Oracle과 이름, 동작이 동일합니다.', 23),
    ('MOD', '숫자', 'MOD(피제수, 제수)', '두 숫자를 나눈 나머지를 반환합니다.', '두 숫자를 나눈 나머지를 반환합니다.', '[{"formula":"MOD(10, 3)","description":"10을 3으로 나눈 나머지인 1을 반환합니다.","result":"1"}]', '음수 처리 방식이 Oracle과 다를 수 있습니다. Oracle은 결과 부호가 피제수를 따르는 반면(MOD(-10,3)=-1), 일부 Calcite 방언은 제수의 부호를 따르도록 구현되어 있어 음수 연산 시 결과 확인이 필요합니다.', 24),
    ('POWER', '숫자', 'POWER(밑수, 지수)', '숫자의 거듭제곱을 계산합니다.', '숫자의 거듭제곱을 계산합니다.', '[{"formula":"POWER(2, 10)","description":"2의 10제곱인 1024를 반환합니다.","result":"1024"}]', 'Oracle과 이름, 동작이 동일합니다.', 25),
    ('SQRT', '숫자', 'SQRT(숫자)', '숫자의 제곱근을 계산합니다.', '숫자의 제곱근을 계산합니다.', '[{"formula":"SQRT(16)","description":"16의 제곱근인 4를 반환합니다.","result":"4"}]', 'Oracle과 이름, 동작이 동일합니다.', 26),
    ('EXP', '숫자', 'EXP(지수)', '자연상수 e의 거듭제곱을 계산합니다.', '자연상수 e의 거듭제곱을 계산합니다.', '[{"formula":"EXP(1)","description":"e의 1제곱인 약 2.71828을 반환합니다.","result":"약 2.71828"}]', 'Oracle과 이름, 동작이 동일합니다.', 27),
    ('LN', '숫자', 'LN(숫자)', '숫자의 자연로그(밑 e)를 계산합니다.', '숫자의 자연로그(밑 e)를 계산합니다.', '[{"formula":"LN(2.71828)","description":"자연로그 값인 약 1을 반환합니다.","result":"약 1"}]', 'Oracle과 이름, 동작이 동일합니다.', 28),
    ('LOG10', '숫자', 'LOG10(숫자)', '숫자의 상용로그(밑 10)를 계산합니다.', '숫자의 상용로그(밑 10)를 계산합니다.', '[{"formula":"LOG10(100)","description":"100의 상용로그 값인 2를 반환합니다.","result":"2"}]', 'Oracle은 LOG(밑수, 진수) 형태로 밑을 자유롭게 지정하는 함수를 기본으로 사용하고 LOG10은 별도 제공하지 않는 경우가 있어, 인자 순서와 함수명에 유의해야 합니다.', 29),
    ('SIGN', '숫자', 'SIGN(숫자)', '숫자의 부호를 -1, 0, 1로 반환합니다.', '숫자의 부호를 -1, 0, 1로 반환합니다.', '[{"formula":"SIGN(-7)","description":"음수이므로 -1을 반환합니다.","result":"-1"}]', 'Oracle과 이름, 동작이 동일합니다.', 30),
    ('CURRENT_DATE', '날짜/시간', 'CURRENT_DATE', '현재 날짜를 반환합니다.', '현재 날짜를 반환합니다.', '[{"formula":"CURRENT_DATE","description":"오늘 날짜인 2026-09-10을 반환합니다.","result":"2026-09-10"}]', 'Oracle은 SYSDATE(현재 날짜+시간)를 주로 사용하며 CURRENT_DATE는 세션 타임존 기준으로 별도 존재합니다. 이름은 같지만 Oracle에서 더 널리 쓰이는 함수는 SYSDATE라는 점에서 혼동됩니다.', 31),
    ('CURRENT_TIME', '날짜/시간', 'CURRENT_TIME', '현재 시각(시:분:초)을 반환합니다.', '현재 시각(시:분:초)을 반환합니다.', '[{"formula":"CURRENT_TIME","description":"현재 시각인 15:30:00을 반환합니다.","result":"15:30:00"}]', 'Oracle에는 CURRENT_TIME 함수가 없으며, TO_CHAR(SYSDATE,''HH24:MI:SS'')로 대체해야 합니다.', 32),
    ('CURRENT_TIMESTAMP', '날짜/시간', 'CURRENT_TIMESTAMP', '현재 날짜와 시각(타임스탬프)을 반환합니다.', '현재 날짜와 시각(타임스탬프)을 반환합니다.', '[{"formula":"CURRENT_TIMESTAMP","description":"현재 날짜와 시각인 2026-09-10 15:30:00을 반환합니다.","result":"2026-09-10 15:30"}]', 'Oracle에도 동일한 이름의 함수가 있지만, Oracle의 CURRENT_TIMESTAMP는 세션 타임존이 포함된 값을 반환하고 SYSTIMESTAMP는 DB 서버의 타임존 기준값을 반환한다는 차이가 있습니다.', 33),
    ('LOCALTIME', '날짜/시간', 'LOCALTIME', '타임존 정보 없이 현재 시각을 반환합니다.', '타임존 정보 없이 현재 시각을 반환합니다.', '[{"formula":"LOCALTIME","description":"타임존 정보가 없는 현재 시각 15:30:00을 반환합니다.","result":"15:30:00"}]', 'Oracle에는 LOCALTIME이 없으며 LOCALTIMESTAMP만 지원합니다.', 34),
    ('LOCALTIMESTAMP', '날짜/시간', 'LOCALTIMESTAMP', '타임존 정보 없이 현재 날짜와 시각을 반환합니다.', '타임존 정보 없이 현재 날짜와 시각을 반환합니다.', '[{"formula":"LOCALTIMESTAMP","description":"타임존 정보가 없는 현재 날짜/시각을 반환합니다.","result":"2026-09-10 15:30"}]', 'Oracle과 이름은 같지만, Oracle의 LOCALTIMESTAMP는 세션 타임존 기준이라는 점에서 정의가 약간 다릅니다.', 35),
    ('EXTRACT', '날짜/시간', 'EXTRACT(추출단위 FROM 날짜)', '날짜/시간에서 특정 부분(연,월,일 등)을 추출합니다.', '날짜/시간에서 특정 부분(연,월,일 등)을 추출합니다.', '[{"formula":"EXTRACT(MONTH FROM DATE ''2026-09-10'')","description":"날짜에서 월 부분인 9를 반환합니다.","result":"9"}]', 'Oracle과 구문 및 동작이 동일하여 혼동 우려가 적습니다.', 36),
    ('DATE_TRUNC', '날짜/시간', 'DATE_TRUNC(절삭단위, 날짜)', '날짜를 지정 단위 기준으로 절삭(내림)합니다.', '날짜를 지정 단위 기준으로 절삭(내림)합니다.', '[{"formula":"DATE_TRUNC(''MONTH'', DATE ''2026-09-10'')","description":"월 단위로 절삭한 2026-09-01을 반환합니다.","result":"2026-09-01"}]', 'Oracle은 TRUNC(날짜, 포맷문자열) 구문을 사용하며 인자 순서(날짜가 먼저, 단위가 나중)와 함수명 자체가 달라 매우 혼동되기 쉬운 함수입니다.', 37),
    ('TIMESTAMPADD', '날짜/시간', 'TIMESTAMPADD(단위, 더할값, 날짜)', '날짜/시간에 지정한 단위만큼 더합니다.', '날짜/시간에 지정한 단위만큼 더합니다.', '[{"formula":"TIMESTAMPADD(MONTH, 3, DATE ''2026-09-10'')","description":"3개월을 더한 2026-12-10을 반환합니다.","result":"2026-12-10"}]', 'Oracle은 월 단위에 한해 ADD_MONTHS(날짜, 개월수) 전용 함수를 사용하며, 일/시/분 단위는 날짜 + INTERVAL 구문을 사용합니다. Calcite처럼 통합된 TIMESTAMPADD 함수가 없어 혼동이 발생합니다.', 38),
    ('TIMESTAMPDIFF', '날짜/시간', 'TIMESTAMPDIFF(단위, 시작날짜, 종료날짜)', '두 날짜/시간의 차이를 지정 단위로 계산합니다.', '두 날짜/시간의 차이를 지정 단위로 계산합니다.', '[{"formula":"TIMESTAMPDIFF(DAY, DATE ''2026-09-01'', DATE ''2026-09-10'')","description":"두 날짜의 차이인 9(일)를 반환합니다.","result":"9"}]', 'Oracle은 날짜끼리 단순히 빼면 일수 차이가 숫자로 계산되며(종료일-시작일), 월 단위 차이는 MONTHS_BETWEEN 함수를 별도로 사용해야 합니다. 통합 함수가 없어 계산 방식 자체가 다릅니다.', 39),
    ('DAYOFWEEK', '날짜/시간', 'DAYOFWEEK(날짜)', '날짜가 요일 중 몇 번째 요일인지 반환합니다.', '날짜가 요일 중 몇 번째 요일인지 반환합니다.', '[{"formula":"DAYOFWEEK(DATE ''2026-09-10'')","description":"해당 날짜의 요일 번호(예: 목요일=5)를 반환합니다.","result":"5 (목요일)"}]', 'Oracle에는 DAYOFWEEK 함수가 없으며 TO_CHAR(날짜,''D'')로 요일 번호를, TO_CHAR(날짜,''DAY'')로 요일명을 구해야 합니다.', 40),
    ('LAST_DAY', '날짜/시간', 'LAST_DAY(날짜)', '해당 날짜가 속한 달의 마지막 날짜를 반환합니다.', '해당 날짜가 속한 달의 마지막 날짜를 반환합니다.', '[{"formula":"LAST_DAY(DATE ''2026-02-10'')","description":"2월의 마지막 날짜인 2026-02-28을 반환합니다.","result":"2026-02-28"}]', 'Oracle에도 동일한 이름과 기능의 함수가 있어 혼동 우려가 적습니다.', 41),
    ('DATE_FORMAT', '날짜/시간', 'DATE_FORMAT(날짜, 포맷문자열)', '날짜를 지정한 포맷의 문자열로 변환합니다.', '날짜를 지정한 포맷의 문자열로 변환합니다.', '[{"formula":"DATE_FORMAT(DATE ''2026-09-10'', ''yyyy-MM-dd'')","description":"지정 포맷으로 변환한 문자열 ''2026-09-10''을 반환합니다.","result":"2026-09-10"}]', 'Oracle은 TO_CHAR(날짜, 포맷문자열)를 사용하며, 포맷 표기법도 Oracle은 ''YYYY-MM-DD''(대문자, Oracle 전용 포맷모델) 방식인 반면 Calcite/MySQL 계열은 ''yyyy-MM-dd''(Java 스타일) 표기를 사용해 포맷 문자 자체가 다릅니다.', 42),
    ('CASE WHEN', '조건부/NULL처리', 'CASE WHEN 조건1 THEN 값1 [WHEN 조건2 THEN 값2 ...] [ELSE 기본값] END', '조건에 따라 다른 값을 반환합니다.', '조건에 따라 다른 값을 반환합니다.', '[{"formula":"CASE WHEN 급여 > 5000 THEN ''고액'' ELSE ''일반'' END","description":"급여가 5000 초과이면 ''고액'', 아니면 ''일반''을 반환합니다.","result":"급여 > 5000: 고액 / 그 외: 일반"}]', 'Oracle과 구문 및 동작이 완전히 동일한 표준 SQL 문법으로, 혼동 우려가 없습니다.', 43),
    ('COALESCE', '조건부/NULL처리', 'COALESCE(값1, 값2, ...)', '여러 값 중 첫 번째로 NULL이 아닌 값을 반환합니다.', '여러 값 중 첫 번째로 NULL이 아닌 값을 반환합니다.', '[{"formula":"COALESCE(NULL, NULL, ''기본값'')","description":"앞의 두 값이 NULL이므로 세 번째 값인 ''기본값''을 반환합니다.","result":"기본값"}]', 'Oracle과 이름, 동작이 동일한 표준 함수입니다. 다만 Oracle 개발자들은 관습적으로 NVL을 더 자주 사용하므로 실무에서 두 함수를 혼용하는 경우가 많습니다.', 44),
    ('NULLIF', '조건부/NULL처리', 'NULLIF(값1, 값2)', '두 값이 같으면 NULL을, 다르면 첫 번째 값을 반환합니다.', '두 값이 같으면 NULL을, 다르면 첫 번째 값을 반환합니다.', '[{"formula":"NULLIF(10, 10)","description":"두 값이 같으므로 NULL을 반환합니다.","result":"NULL"}]', 'Oracle과 이름, 동작이 동일하여 혼동 우려가 적습니다.', 45),
    ('NVL', '조건부/NULL처리', 'NVL(값, 대체값)', '값이 NULL이면 대체값을, 아니면 원래 값을 반환합니다.', '값이 NULL이면 대체값을, 아니면 원래 값을 반환합니다.', '[{"formula":"NVL(NULL, 0)","description":"값이 NULL이므로 대체값인 0을 반환합니다.","result":"0"}]', 'Oracle 고유 함수이지만 Calcite도 Oracle 방언 라이브러리를 활성화하면 지원합니다. 다만 표준 방언에서는 지원되지 않을 수 있어 COALESCE로 대체하는 것이 안전합니다.', 46),
    ('DECODE', '조건부/NULL처리', 'DECODE(비교대상, 값1, 결과1, 값2, 결과2, ..., 기본결과)', '값을 여러 조건과 비교해 일치하는 결과를 반환합니다(IF-THEN-ELSE 체인).', '값을 여러 조건과 비교해 일치하는 결과를 반환합니다(IF-THEN-ELSE 체인).', '[{"formula":"DECODE(부서코드, 10, ''인사팀'', 20, ''영업팀'', ''기타'')","description":"부서코드가 10이면 ''인사팀'', 20이면 ''영업팀'', 그 외는 ''기타''를 반환합니다.","result":"10: 인사팀 / 20: 영업팀 / 그 외: 기타"}]', 'Oracle 고유의 레거시 함수로, Calcite는 Oracle 방언 라이브러리 활성화 시에만 지원됩니다. 표준 SQL 환경에서는 CASE WHEN으로 대체해야 하는 경우가 많아 혼동됩니다.', 47),
    ('IF', '조건부/NULL처리', 'IF(조건, 참일때값, 거짓일때값)', '조건이 참/거짓인지에 따라 값을 반환합니다.', '조건이 참/거짓인지에 따라 값을 반환합니다.', '[{"formula":"IF(재고 > 0, ''판매중'', ''품절'')","description":"재고가 0보다 크면 ''판매중'', 아니면 ''품절''을 반환합니다.","result":"재고 > 0: 판매중 / 그 외: 품절"}]', 'Oracle SQL 문에는 IF 함수가 없습니다(PL/SQL 절차문에서의 IF문과는 다름). Hive/MySQL 계열 방언 함수로, Oracle에서는 CASE WHEN으로만 표현 가능합니다.', 48),
    ('COUNT', '집계함수', 'COUNT(*|[DISTINCT] 컬럼)', '조건에 맞는 행의 개수를 계산합니다.', '조건에 맞는 행의 개수를 계산합니다.', '[{"formula":"COUNT(DISTINCT 부서코드)","description":"중복을 제거한 부서코드의 개수를 반환합니다.","result":"부서코드 고유 개수 (데이터에 따라 달라짐)"}]', 'Oracle과 구문 및 동작이 동일합니다.', 49),
    ('SUM', '집계함수', 'SUM(숫자컬럼)', '숫자 컬럼 값들의 합계를 계산합니다.', '숫자 컬럼 값들의 합계를 계산합니다.', '[{"formula":"SUM(급여)","description":"전체 급여의 합계를 반환합니다.","result":"급여 합계 (데이터에 따라 달라짐)"}]', 'Oracle과 동일합니다. 다만 Oracle은 SUM 결과에 대해 정밀도(NUMBER 타입) 처리 방식이 Calcite의 기본 타입 추론과 다를 수 있어 대용량 합계 시 타입 확인이 필요합니다.', 50),
    ('AVG', '집계함수', 'AVG(숫자컬럼)', '숫자 컬럼 값들의 평균을 계산합니다.', '숫자 컬럼 값들의 평균을 계산합니다.', '[{"formula":"AVG(급여)","description":"전체 급여의 평균값을 반환합니다.","result":"급여 평균 (데이터에 따라 달라짐)"}]', 'Oracle과 동일합니다.', 51),
    ('MIN', '집계함수', 'MIN(컬럼)', '컬럼 값 중 최솟값을 반환합니다.', '컬럼 값 중 최솟값을 반환합니다.', '[{"formula":"MIN(입사일)","description":"가장 빠른 입사일을 반환합니다.","result":"가장 빠른 입사일 (데이터에 따라 달라짐)"}]', 'Oracle과 동일합니다.', 52),
    ('MAX', '집계함수', 'MAX(컬럼)', '컬럼 값 중 최댓값을 반환합니다.', '컬럼 값 중 최댓값을 반환합니다.', '[{"formula":"MAX(급여)","description":"가장 높은 급여값을 반환합니다.","result":"가장 높은 급여 (데이터에 따라 달라짐)"}]', 'Oracle과 동일합니다.', 53),
    ('LISTAGG', '집계함수', 'LISTAGG(컬럼, 구분자) WITHIN GROUP (ORDER BY 정렬컬럼)', '그룹 내 여러 행의 값을 하나의 문자열로 연결합니다.', '그룹 내 여러 행의 값을 하나의 문자열로 연결합니다.', '[{"formula":"LISTAGG(사원명, '','') WITHIN GROUP (ORDER BY 사원명)","description":"그룹 내 사원명을 쉼표로 연결한 하나의 문자열을 반환합니다.","result":"사원명1,사원명2,… (이름순)"}]', 'Oracle과 함수명, 기본 구문이 동일하지만, 결과 문자열 길이 제한(Oracle 4000바이트 초과 시 에러)이나 중복 제거 옵션 등 세부 동작에 방언별 차이가 있을 수 있어 대용량 그룹 연결 시 유의해야 합니다.', 54),
    ('ROW_NUMBER', '윈도우함수', 'ROW_NUMBER() OVER (PARTITION BY 그룹컬럼 ORDER BY 정렬컬럼)', '파티션 내에서 순서대로 고유한 순번을 부여합니다.', '파티션 내에서 순서대로 고유한 순번을 부여합니다.', '[{"formula":"ROW_NUMBER() OVER (PARTITION BY 부서 ORDER BY 급여 DESC)","description":"부서별로 급여가 높은 순서대로 1,2,3...의 고유 순번을 부여합니다.","result":"부서별 1, 2, 3, …"}]', 'Oracle과 구문 및 동작이 완전히 동일합니다.', 55),
    ('RANK', '윈도우함수', 'RANK() OVER (PARTITION BY 그룹컬럼 ORDER BY 정렬컬럼)', '동일 값에는 같은 순위를 부여하고, 다음 순위는 건너뜁니다.', '동일 값에는 같은 순위를 부여하고, 다음 순위는 건너뜁니다.', '[{"formula":"RANK() OVER (ORDER BY 점수 DESC)","description":"점수가 같으면 같은 순위(예: 1,2,2,4)를 부여하며 3위는 건너뜁니다.","result":"1, 2, 2, 4, …"}]', 'Oracle과 동작이 동일합니다.', 56),
    ('DENSE_RANK', '윈도우함수', 'DENSE_RANK() OVER (PARTITION BY 그룹컬럼 ORDER BY 정렬컬럼)', '동일 값에는 같은 순위를 부여하되, 다음 순위를 건너뛰지 않습니다.', '동일 값에는 같은 순위를 부여하되, 다음 순위를 건너뛰지 않습니다.', '[{"formula":"DENSE_RANK() OVER (ORDER BY 점수 DESC)","description":"점수가 같으면 같은 순위(예: 1,2,2,3)를 부여하며 순위를 건너뛰지 않습니다.","result":"1, 2, 2, 3, …"}]', 'Oracle과 동작이 동일합니다. RANK와의 차이(순위 건너뜀 여부)를 혼동하지 않도록 주의해야 합니다.', 57),
    ('LAG', '윈도우함수', 'LAG(컬럼, 이전행수, 기본값) OVER (ORDER BY 정렬컬럼)', '현재 행 기준 이전 행의 값을 가져옵니다.', '현재 행 기준 이전 행의 값을 가져옵니다.', '[{"formula":"LAG(매출, 1) OVER (ORDER BY 월)","description":"직전 월의 매출 값을 가져옵니다.","result":"직전 월 매출 (첫 행은 NULL)"}]', 'Oracle과 구문 및 동작이 동일합니다.', 58),
    ('LEAD', '윈도우함수', 'LEAD(컬럼, 다음행수, 기본값) OVER (ORDER BY 정렬컬럼)', '현재 행 기준 다음 행의 값을 가져옵니다.', '현재 행 기준 다음 행의 값을 가져옵니다.', '[{"formula":"LEAD(매출, 1) OVER (ORDER BY 월)","description":"다음 월의 매출 값을 가져옵니다.","result":"다음 월 매출 (마지막 행은 NULL)"}]', 'Oracle과 구문 및 동작이 동일합니다.', 59),
    ('NTILE', '윈도우함수', 'NTILE(그룹개수) OVER (PARTITION BY 그룹컬럼 ORDER BY 정렬컬럼)', '파티션 내 행들을 지정한 개수의 그룹으로 균등 분할합니다.', '파티션 내 행들을 지정한 개수의 그룹으로 균등 분할합니다.', '[{"formula":"NTILE(4) OVER (ORDER BY 급여 DESC)","description":"급여 순으로 정렬한 후 전체를 4개 그룹(4분위)으로 나눈 그룹번호를 반환합니다.","result":"1~4"}]', 'Oracle과 구문 및 동작이 동일합니다.', 60);
